export const CRM_HTML = "<!DOCTYPE html><html lang=\"es\"><head><meta charset=\"utf-8\"><meta name=\"viewport\" content=\"width=device-width, initial-scale=1\"><meta name=\"theme-color\" content=\"#24362c\"><meta name=\"mobile-web-app-capable\" content=\"yes\"><meta name=\"apple-mobile-web-app-capable\" content=\"yes\"><meta name=\"apple-mobile-web-app-status-bar-style\" content=\"default\"><meta name=\"apple-mobile-web-app-title\" content=\"Bandeja\"><link rel=\"manifest\" href=\"/bandeja/manifest.webmanifest\"><link rel=\"icon\" href=\"/bandeja/icono/192.png\"><link rel=\"apple-touch-icon\" href=\"/bandeja/icono/192.png\"><title>Bandeja de Extensiones</title><style>@font-face{font-family:Atkinson Hyperlegible;font-style:normal;font-display:swap;font-weight:400;src:url(data:font/woff2;base64,)format(\"woff2\"),url(data:font/woff;base64,)format(\"woff\")}@font-face{font-family:Atkinson Hyperlegible;font-style:normal;font-display:swap;font-weight:700;src:url(data:font/woff2;base64,)format(\"woff2\"),url(data:font/woff;base64,)format(\"woff\")}@font-face{font-family:Petrona;font-style:normal;font-display:swap;font-weight:500;src:url(data:font/woff2;base64,)format(\"woff2\"),url(data:font/woff;base64,)format(\"woff\")}:root{--paper:#f3eee3;--sage:#3a5344;--sage-deep:#24362c;--ink:#231e1a;--ink-soft:#3f3832;--cedar:#6a4e38;--persimmon:#b4532a;--persimmon-deep:#8a3b1c;--line:#e4d6c2;color-scheme:light;caret-color:var(--persimmon)}*{box-sizing:border-box}html,body{min-height:100%;margin:0}body{color:var(--ink);background:var(--paper);font-family:Atkinson Hyperlegible,Segoe UI,sans-serif;font-size:1.0625rem;line-height:1.45}::selection{background:var(--sage);color:var(--paper)}:focus-visible{outline:2px solid var(--persimmon);outline-offset:3px}*{scrollbar-color:var(--sage) var(--paper)}h1,h2,strong.cifra{font-family:Petrona,Palatino,serif;font-weight:500}h2{margin:0;font-size:1.25rem}.skip{color:var(--ink);background:#fffdf8;padding:.4rem .6rem;position:absolute;top:-3rem;left:.75rem}.skip:focus{top:.75rem}button,input,textarea{font:inherit}button{cursor:pointer}.esperando #app,.esperando #entrar,.sin-sesion #app,.con-sesion #entrar{display:none}#entrar{background:#fffdf8;flex-direction:column;max-width:24rem;margin:12vh auto;padding:1.5rem;display:flex}#entrar h1{margin:0 0 .4rem;font-size:2rem}label{margin:1rem 0 .35rem;font-weight:700;display:block}input,textarea{border:1px solid var(--cedar);background:var(--paper);width:100%;color:var(--ink);padding:.7rem .75rem}textarea{resize:vertical;min-height:3.4rem}.clave{position:relative}.clave input{padding-right:6.2rem}#ver-clave{height:100%;color:var(--sage-deep);background:0 0;border:0;margin:0;padding:0 .8rem;font-weight:700;position:absolute;top:0;right:0}button.enviar,#entrar button[type=submit],#instalar-ahora{background:var(--sage);color:var(--paper);border:0;margin-top:.8rem;padding:.75rem 1rem}button.enviar:disabled,#entrar button[type=submit]:disabled{opacity:.55}#entrar .instalar{color:var(--sage-deep);border:1px solid var(--cedar);background:0 0;margin-top:.7rem;padding:.7rem 1rem}#guia{z-index:5;background:#231e1a73;justify-content:center;align-items:end;padding:1rem;display:grid;position:fixed;inset:0}#guia[hidden]{display:none}#guia article{width:min(28rem,100%);max-height:calc(100dvh - 2rem);color:var(--ink);background:#fffdf8;padding:1.15rem 1.2rem 1.25rem;overflow:auto}#guia h2{margin:0 0 .35rem;font-size:1.7rem}#guia p{margin:.35rem 0 .7rem}#guia h3{margin:.8rem 0 .25rem;font-family:Atkinson Hyperlegible,Segoe UI,sans-serif;font-size:1.05rem}#guia ol{margin:0;padding-left:1.2rem}#guia li+li{margin-top:.25rem}#instalar-ahora{width:100%;margin-top:.9rem}#cerrar-guia{color:var(--sage-deep);background:0 0;border:0;margin-top:.45rem;padding:.45rem 0;font-weight:700}.acciones{align-items:center;gap:.9rem;display:flex}.aviso{color:var(--persimmon-deep);margin:.6rem 0 0}#avisos-nota{color:var(--ink);background:#fffdf8;margin:0;padding:.75rem 1.25rem}header.barra{background:var(--sage-deep);color:var(--paper);justify-content:space-between;align-items:center;gap:1rem;padding:.9rem 1.25rem;display:flex}header.barra h1{letter-spacing:-.03em;margin:0;font-size:1.8rem}.salir{color:var(--paper);background:0 0;border:0;margin:0;padding:.4rem .2rem}#estados{grid-template-columns:1.35fr 1fr 1fr;gap:.8rem;padding:1rem 1.25rem .4rem;display:grid}#ver-papelera,#tirar,#restaurar,#grabar,.archivo{color:var(--sage-deep);border:1px solid var(--cedar);background:0 0;padding:.45rem .7rem}#ver-papelera{margin:0 1.25rem .8rem}#ver-papelera[aria-pressed=true]{background:var(--paper-deep)}#tirar{color:var(--persimmon-deep);border-color:var(--persimmon)}.acciones-hilo,.adjuntos{flex-wrap:wrap;align-items:center;gap:.5rem;margin-top:.55rem;display:flex}.archivo{position:relative}.archivo input{clip:rect(0 0 0 0);width:1px;height:1px;position:absolute;overflow:hidden}#nota-archivo,#nota-audio{color:var(--ink-soft);margin:.4rem 0 0}#nota-archivo:empty{display:none}.texto img{max-width:min(100%,22rem);height:auto;margin-top:.45rem;display:block}.texto audio{width:min(100%,22rem);margin-top:.45rem;display:block}.estado{text-align:left;border:1px solid var(--line);color:var(--ink);background:#fffdf8;padding:.7rem .9rem .8rem}.estado strong{font-variant-numeric:tabular-nums;font-size:2.6rem;line-height:.9;display:block}.estado.activo strong{font-size:3.4rem}.estado[data-estado=pendiente].activo{border-color:var(--persimmon);background:#f6e4d8}.estado[data-estado=pendiente].activo strong,.estado[data-estado=pendiente].activo span{color:var(--persimmon-deep)}.estado[data-estado=vista].activo strong{color:var(--cedar)}.estado[data-estado=atendida].activo strong{color:var(--sage-deep)}body.con-sesion{flex-direction:column;height:100dvh;display:flex;overflow:hidden}body.con-sesion #app{flex-direction:column;flex:1;min-height:0;display:flex}.cuerpo{border-top:1px solid var(--line);flex:1;grid-template-rows:minmax(0,1fr);grid-template-columns:minmax(16rem,28rem) 1fr;min-height:0;display:grid}#lista{flex-direction:column;min-height:0;display:flex;overflow:auto}.hilo{text-align:left;border:0;border-bottom:1px solid var(--line);width:100%;color:inherit;background:0 0;grid-template-columns:.55rem 1fr auto;gap:.75rem;padding:.9rem 1rem;display:grid}.hilo.activo{background:#fffdf8}.hilo b{font-size:1rem;display:block}.hilo span{color:var(--ink-soft);font-size:.92rem}.hilo time{color:var(--cedar);font-variant-numeric:tabular-nums;font-size:.82rem}.marca{background:var(--sage);width:.55rem;height:.55rem;margin-top:.35rem;display:block}.marca.pendiente{background:var(--persimmon)}.marca.vista{background:var(--cedar)}#chat{border-left:1px solid var(--line);background:#fffdf8;grid-template-rows:auto 1fr auto;min-height:0;transition:background-color .2s cubic-bezier(.16,1,.3,1);display:grid;overflow:hidden}#chat[data-estado=pendiente]{background:#f6e4d8}#chat[data-estado=vista]{background:#efe4d6}#chat[data-estado=atendida]{background:#e4eee8}.quien{background:#fffdf8;justify-content:space-between;align-items:center;gap:1rem;padding:.9rem 1.1rem;display:flex}.quien p{color:var(--ink-soft);margin:.15rem 0 0}#volver{color:var(--sage-deep);background:0 0;border:0;padding:0;display:none}#mensajes{min-height:0;padding:1rem 1.1rem;overflow:auto}.linea{grid-template-columns:6.2rem 1fr;gap:.75rem;margin:0 0 .8rem;display:grid}.linea time{color:var(--cedar);font-variant-numeric:tabular-nums;white-space:nowrap;padding-top:.35rem;font-size:.82rem}.texto{background:#fffdf8;margin:0;padding:.65rem .75rem}.texto a{color:var(--sage-deep)}#respuesta{background:#fffdf8;padding:.9rem 1.1rem 1.1rem}.vacio{color:var(--ink-soft);padding:1rem}@media (prefers-reduced-motion:reduce){#chat{transition:none}}@media (width<=720px){#estados{grid-template-columns:repeat(3,1fr)}textarea{min-height:2.6rem}#respuesta{padding:.55rem .8rem .7rem}.estado strong,.estado.activo strong{font-size:2rem}.cuerpo{grid-template-columns:1fr}#chat{border-left:0}body.con-sesion.con-chat #lista,body.con-sesion:not(.con-chat) #chat{display:none}body.con-chat #volver{display:inline}}\n</style></head><body class=\"esperando\"><a class=\"skip\" href=\"#lista\">Saltar a las conversaciones</a><form id=\"entrar\" method=\"post\" action=\"/bandeja/entrar\"><h1>Extensiones</h1><p>Entra para leer y contestar los mensajes.</p><p id=\"clave-aviso\" class=\"aviso\" hidden>La clave no coincide.</p><label for=\"clave\">Clave</label><div class=\"clave\"><input id=\"clave\" name=\"clave\" type=\"password\" autocomplete=\"current-password\" required><button id=\"ver-clave\" type=\"button\" aria-pressed=\"false\" aria-label=\"Mostrar clave\">Ver</button></div><button type=\"submit\">Entrar</button><button class=\"instalar\" type=\"button\">Instalar como aplicación</button></form><div id=\"app\"><header class=\"barra\"><h1>Extensiones</h1><div class=\"acciones\"><button id=\"avisos\" class=\"salir\" type=\"button\">Avisos</button><button class=\"instalar salir\" type=\"button\">Instalar</button><form method=\"post\" action=\"/bandeja/salir\"><button class=\"salir\" type=\"submit\">Salir</button></form></div></header><p id=\"envio\" class=\"aviso\" hidden>No se pudo enviar. Revisa el formato, el tamaño y vuelve a intentar.</p><p id=\"avisos-nota\" hidden>En iPhone, instala la bandeja en la pantalla de inicio y ábrela desde ahí. Luego pulsa Avisos.</p><nav id=\"estados\" aria-label=\"Estados\"></nav><button id=\"ver-papelera\" type=\"button\" aria-pressed=\"false\">Papelera</button><div class=\"cuerpo\"><div id=\"lista\"></div><section id=\"chat\"><div class=\"quien\"><div><button id=\"volver\" type=\"button\">Volver</button><h2 id=\"titulo\">Elige una conversación</h2><p id=\"sub\"></p></div><div class=\"acciones-hilo\"><button id=\"tirar\" type=\"button\" hidden>Mover a la papelera</button><button id=\"restaurar\" type=\"button\" hidden>Restaurar</button></div></div><div id=\"mensajes\" aria-live=\"polite\"></div><form id=\"respuesta\" method=\"post\" action=\"/bandeja/responder\" enctype=\"multipart/form-data\" hidden><input id=\"sesion\" name=\"sesion\" type=\"hidden\"><input id=\"telefono\" name=\"telefono\" type=\"hidden\"><label for=\"texto\">Respuesta</label><textarea id=\"texto\" name=\"texto\" maxlength=\"4000\"></textarea><div class=\"adjuntos\"><label class=\"archivo\" for=\"archivo\">Adjuntar archivo<input id=\"archivo\" name=\"archivo\" type=\"file\" accept=\"image/png,image/jpeg,image/webp,.pdf,.doc,.docx,audio/mpeg,audio/mp4,audio/ogg,audio/aac,.mp3,.m4a,.ogg,.opus,.aac\"></label><button id=\"grabar\" type=\"button\">Grabar audio</button></div><p id=\"nota-archivo\"></p><p id=\"nota-audio\" hidden>Este navegador graba un formato que WhatsApp no acepta. Adjunta un mp3, m4a u ogg.</p><button class=\"enviar\" type=\"submit\">Enviar por WhatsApp</button></form></section></div></div><div id=\"guia\" hidden><article role=\"dialog\" aria-modal=\"true\" aria-labelledby=\"guia-titulo\"><h2 id=\"guia-titulo\">Instalar la bandeja</h2><p>Queda en la pantalla del teléfono, con el nombre y el ícono de Extensiones.</p><button id=\"instalar-ahora\" type=\"button\" hidden>Instalar ahora</button><h3>Android</h3><ol><li>Abre esta página en Chrome.</li><li>Pulsa Instalar ahora si aparece arriba.</li><li>Si no aparece, abre el menú de los tres puntos.</li><li>Elige Instalar aplicación o Añadir a pantalla principal.</li></ol><h3>iPhone</h3><ol><li>Abre esta página en Safari.</li><li>Pulsa Compartir, el cuadrado con la flecha.</li><li>Elige Añadir a pantalla de inicio.</li><li>Pulsa Añadir.</li></ol><button id=\"cerrar-guia\" type=\"button\">Cerrar</button></article></div><script>\n      const orden = [\"pendiente\", \"vista\", \"atendida\"];\n      const nombres = { pendiente: \"Pendiente\", vista: \"Vista\", atendida: \"Atendida\", papelera: \"Papelera\" };\n      let grabacion = null;\n      const voces = { paciente: \"Paciente\", bot: \"Menú\", equipo: \"Equipo\" };\n      let sesion = \"\";\n      let firma = \"\";\n      let telefonoAbierto = \"\";\n      const query = () => {\n        const q = new URLSearchParams(location.search);\n        const pedido = q.get(\"e\");\n        const e = orden.includes(pedido) || pedido === \"papelera\" ? pedido : \"pendiente\";\n        return { e, c: q.get(\"c\") || \"\" };\n      };\n      const tituloDe = (telefono) =>\n        telefono.startsWith(\"502\") && telefono.length === 11\n          ? \"+502 \" + telefono.slice(3, 7) + \" \" + telefono.slice(7)\n          : \"+\" + telefono;\n      function sesionVisible(activa) {\n        document.body.classList.toggle(\"sin-sesion\", !activa);\n        document.body.classList.toggle(\"con-sesion\", activa);\n        document.body.classList.remove(\"esperando\");\n      }\n      function ir(estado, telefono) {\n        const q = new URLSearchParams();\n        q.set(\"e\", estado);\n        if (telefono) q.set(\"c\", telefono);\n        history.pushState({}, \"\", \"/bandeja?\" + q);\n        firma = \"\";\n        pedir();\n      }\n      async function abrir(telefono, estado) {\n        const destino = estado === \"pendiente\" ? \"vista\" : estado;\n        if (estado === \"pendiente\" && sesion) {\n          const cuerpo = new URLSearchParams({ sesion, telefono });\n          await fetch(\"/bandeja/ver\", { method: \"POST\", body: cuerpo });\n        }\n        ir(destino, telefono);\n      }\n      function pintar(datos) {\n        sesion = datos.sesion || sesion;\n        const { e, c } = query();\n        document.body.classList.toggle(\"con-chat\", Boolean(c));\n        const marca = orden.map((estado) => estado + datos.conteos[estado]).join() + \"|\" + (datos.papelera || 0) + \"|\" + datos.hilos.map((h) => h.telefono + h.ultimo).join() + \"|\" + datos.lineas.map((l) => l.id + (l.mime || \"\")).join() + \"|\" + c + datos.estado;\n        const estados = document.querySelector(\"#estados\");\n        const lista = document.querySelector(\"#lista\");\n        const mensajes = document.querySelector(\"#mensajes\");\n        const chat = document.querySelector(\"#chat\");\n        if (marca !== firma) {\n          const cerca = window.innerHeight + window.scrollY >= document.documentElement.scrollHeight - 140;\n          estados.replaceChildren();\n          for (const estado of orden) {\n            const boton = document.createElement(\"button\");\n            boton.type = \"button\";\n            boton.className = \"estado\" + (estado === e ? \" activo\" : \"\");\n            boton.dataset.estado = estado;\n            boton.setAttribute(\"aria-pressed\", estado === e ? \"true\" : \"false\");\n            const cifra = document.createElement(\"strong\");\n            cifra.className = \"cifra\";\n            cifra.textContent = String(datos.conteos[estado] || 0);\n            const nombre = document.createElement(\"span\");\n            nombre.textContent = nombres[estado];\n            boton.append(cifra, nombre);\n            boton.addEventListener(\"click\", () => ir(estado, \"\"));\n            estados.append(boton);\n          }\n          lista.replaceChildren();\n          if (!datos.hilos.length) lista.append(vacio(e === \"papelera\" ? \"Nada en la papelera.\" : \"Nada en \" + nombres[e].toLowerCase() + \".\"));\n          for (const hilo of datos.hilos) {\n            const boton = document.createElement(\"button\");\n            boton.type = \"button\";\n            boton.className = \"hilo\" + (hilo.telefono === c ? \" activo\" : \"\");\n            const marcaEstado = document.createElement(\"i\");\n            marcaEstado.className = \"marca \" + hilo.estado;\n            const texto = document.createElement(\"span\");\n            const nombre = document.createElement(\"b\");\n            nombre.textContent = hilo.titulo;\n            const vista = document.createElement(\"span\");\n            vista.textContent = hilo.vista;\n            texto.append(nombre, vista);\n            const hora = document.createElement(\"time\");\n            hora.textContent = new Intl.DateTimeFormat(\"es-GT\", { hour: \"2-digit\", minute: \"2-digit\", timeZone: \"America/Guatemala\" }).format(hilo.ultimo);\n            boton.append(marcaEstado, texto, hora);\n            boton.addEventListener(\"click\", () => abrir(hilo.telefono, hilo.estado));\n            lista.append(boton);\n          }\n          mensajes.replaceChildren();\n          if (!c) mensajes.append(vacio(\"Elige una conversación.\"));\n          else if (!datos.lineas.length) mensajes.append(vacio(\"Todavía no hay mensajes guardados.\"));\n          else {\n            for (const linea of datos.lineas) {\n              const fila = document.createElement(\"article\");\n              fila.className = \"linea\";\n              const hora = document.createElement(\"time\");\n              hora.textContent = linea.hora;\n              const cuerpo = document.createElement(\"p\");\n              cuerpo.className = \"texto\";\n              cuerpo.textContent = (voces[linea.quien] || \"Equipo\") + \" · \" + linea.texto;\n              mostrarMedio(linea, cuerpo);\n              fila.append(hora, cuerpo);\n              mensajes.append(fila);\n            }\n          }\n          chat.dataset.estado = datos.estado || \"\";\n          document.querySelector(\"#titulo\").textContent = c ? tituloDe(c) : \"Elige una conversación\";\n          document.querySelector(\"#sub\").textContent = datos.estado ? nombres[datos.estado] : \"\";\n          document.querySelector(\"#tirar\").hidden = !c || datos.estado !== \"atendida\";\n          document.querySelector(\"#restaurar\").hidden = !c || datos.estado !== \"papelera\";\n          firma = marca;\n          if (cerca) mensajes.scrollTop = mensajes.scrollHeight;\n        }\n        const respuesta = document.querySelector(\"#respuesta\");\n        document.querySelector(\"#sesion\").value = sesion;\n        const campo = document.querySelector(\"#telefono\");\n        if (campo.value !== c) {\n          campo.value = c;\n          if (telefonoAbierto !== c) {\n            document.querySelector(\"#texto\").value = \"\";\n            document.querySelector(\"#archivo\").value = \"\";\n            document.querySelector(\"#nota-archivo\").textContent = \"\";\n          }\n          telefonoAbierto = c;\n        }\n        respuesta.hidden = !c || datos.estado === \"papelera\";\n        const verPapelera = document.querySelector(\"#ver-papelera\");\n        verPapelera.textContent = \"Papelera (\" + (datos.papelera || 0) + \")\";\n        verPapelera.setAttribute(\"aria-pressed\", e === \"papelera\" ? \"true\" : \"false\");\n        document.querySelector(\"#envio\").hidden = new URLSearchParams(location.search).get(\"x\") !== \"envio\";\n      }\n      function mostrarMedio(linea, cuerpo) {\n        if (!linea.medio) return;\n        const url = \"/bandeja/medio/\" + encodeURIComponent(linea.medio);\n        const mime = linea.mime || \"\";\n        if (mime.startsWith(\"image/\")) {\n          const img = document.createElement(\"img\");\n          img.src = url;\n          img.alt = linea.nombre || \"Imagen enviada\";\n          cuerpo.append(img);\n          return;\n        }\n        if (mime.startsWith(\"audio/\")) {\n          const audio = document.createElement(\"audio\");\n          audio.controls = true;\n          audio.src = url;\n          cuerpo.append(audio);\n          return;\n        }\n        const enlace = document.createElement(\"a\");\n        enlace.href = url;\n        enlace.textContent = linea.nombre || \"Ver archivo\";\n        cuerpo.append(document.createTextNode(\" \"), enlace);\n      }\n      async function mover(accion) {\n        const { c } = query();\n        if (!c || !sesion) return;\n        const cuerpo = new URLSearchParams({ sesion, telefono: c, accion });\n        const respuesta = await fetch(\"/bandeja/papelera\", { method: \"POST\", body: cuerpo });\n        if (!respuesta.ok) return;\n        firma = \"\";\n        ir(accion === \"tirar\" ? \"papelera\" : \"atendida\", c);\n      }\n      function vacio(texto) {\n        const p = document.createElement(\"p\");\n        p.className = \"vacio\";\n        p.textContent = texto;\n        return p;\n      }\n      async function pedir() {\n        const { e, c } = query();\n        try {\n          const respuesta = await fetch(\"/bandeja/novedades?e=\" + encodeURIComponent(e) + \"&c=\" + encodeURIComponent(c), { cache: \"no-store\" });\n          if (respuesta.status === 401) {\n            sesionVisible(false);\n            document.querySelector(\"#clave-aviso\").hidden = new URLSearchParams(location.search).get(\"e\") !== \"1\";\n            return;\n          }\n          if (!respuesta.ok) return;\n          sesionVisible(true);\n          pintar(await respuesta.json());\n        } catch {}\n      }\n      function conectar() {\n        if (!document.body.classList.contains(\"con-sesion\")) return;\n        const protocolo = location.protocol === \"https:\" ? \"wss:\" : \"ws:\";\n        const socket = new WebSocket(protocolo + \"//\" + location.host + \"/bandeja/vivo\");\n        socket.onmessage = () => pedir();\n        socket.onclose = () => setTimeout(conectar, 4000);\n      }\n      document.querySelector(\"#ver-clave\").addEventListener(\"click\", () => {\n        const campo = document.querySelector(\"#clave\");\n        const visible = campo.type === \"password\";\n        campo.type = visible ? \"text\" : \"password\";\n        const boton = document.querySelector(\"#ver-clave\");\n        boton.textContent = visible ? \"Ocultar\" : \"Ver\";\n        boton.setAttribute(\"aria-pressed\", visible ? \"true\" : \"false\");\n        boton.setAttribute(\"aria-label\", visible ? \"Ocultar clave\" : \"Mostrar clave\");\n      });\n      const guia = document.querySelector(\"#guia\");\n      const instalarAhora = document.querySelector(\"#instalar-ahora\");\n      let instalacion = null;\n      const yaInstalada = window.matchMedia(\"(display-mode: standalone)\").matches || window.navigator.standalone === true;\n      if (yaInstalada) document.querySelectorAll(\".instalar\").forEach((boton) => { boton.hidden = true; });\n      window.addEventListener(\"beforeinstallprompt\", (evento) => {\n        evento.preventDefault();\n        instalacion = evento;\n        instalarAhora.hidden = false;\n      });\n      document.querySelectorAll(\".instalar\").forEach((boton) => {\n        boton.addEventListener(\"click\", () => { guia.hidden = false; });\n      });\n      instalarAhora.addEventListener(\"click\", async () => {\n        if (!instalacion) return;\n        instalacion.prompt();\n        await instalacion.userChoice;\n        instalacion = null;\n        instalarAhora.hidden = true;\n        guia.hidden = true;\n      });\n      document.querySelector(\"#cerrar-guia\").addEventListener(\"click\", () => { guia.hidden = true; });\n      guia.addEventListener(\"click\", (evento) => { if (evento.target === guia) guia.hidden = true; });\n      function desdeClave(valor) {\n        const base = valor.replace(/-/g, \"+\").replace(/_/g, \"/\");\n        const binario = atob(base + \"=\".repeat((4 - (base.length % 4)) % 4));\n        const bytes = new Uint8Array(binario.length);\n        for (let i = 0; i < binario.length; i++) bytes[i] = binario.charCodeAt(i);\n        return bytes;\n      }\n      async function marcarAvisosActivos() {\n        if (!(\"serviceWorker\" in navigator) || !(\"PushManager\" in window) || Notification.permission !== \"granted\") return;\n        const registro = await navigator.serviceWorker.ready;\n        const actual = await registro.pushManager.getSubscription();\n        if (actual) document.querySelector(\"#avisos\").textContent = \"Avisos activos\";\n      }\n      document.querySelector(\"#avisos\").addEventListener(\"click\", async () => {\n        const nota = document.querySelector(\"#avisos-nota\");\n        const ios = /iPhone|iPad/.test(navigator.userAgent);\n        const instalada = window.matchMedia(\"(display-mode: standalone)\").matches || window.navigator.standalone === true;\n        if (ios && !instalada) {\n          nota.hidden = false;\n          nota.textContent = \"En iPhone, instala la bandeja en la pantalla de inicio y ábrela desde ahí. Luego pulsa Avisos.\";\n          return;\n        }\n        if (!(\"Notification\" in window) || !(\"PushManager\" in window)) {\n          nota.hidden = false;\n          nota.textContent = \"Este navegador no puede mostrar avisos. En Android usa Chrome. En iPhone usa la aplicación instalada.\";\n          return;\n        }\n        const permiso = await Notification.requestPermission();\n        if (permiso !== \"granted\") {\n          nota.hidden = false;\n          nota.textContent = \"El teléfono no permitió los avisos.\";\n          return;\n        }\n        const registro = await navigator.serviceWorker.ready;\n        const clave = await fetch(\"/bandeja/avisos\", { cache: \"no-store\" }).then((respuesta) => respuesta.json());\n        if (!clave.publica) {\n          nota.hidden = false;\n          nota.textContent = \"Los avisos todavía no están configurados.\";\n          return;\n        }\n        let suscripcion = await registro.pushManager.getSubscription();\n        if (!suscripcion) {\n          suscripcion = await registro.pushManager.subscribe({\n            userVisibleOnly: true,\n            applicationServerKey: desdeClave(clave.publica),\n          });\n        }\n        const alta = await fetch(\"/bandeja/avisos\", {\n          method: \"POST\",\n          headers: { \"content-type\": \"application/json\" },\n          body: JSON.stringify(suscripcion),\n        });\n        nota.hidden = !alta.ok;\n        if (alta.ok) document.querySelector(\"#avisos\").textContent = \"Avisos activos\";\n        else nota.textContent = \"No se pudo activar el aviso. Intenta otra vez.\";\n      });\n      if (\"serviceWorker\" in navigator) {\n        navigator.serviceWorker.register(\"/bandeja/sw.js\").then(marcarAvisosActivos);\n      }\n      document.querySelector(\"#volver\").addEventListener(\"click\", () => ir(query().e, \"\"));\n      document.querySelector(\"#ver-papelera\").addEventListener(\"click\", () => ir(\"papelera\", \"\"));\n      document.querySelector(\"#tirar\").addEventListener(\"click\", () => mover(\"tirar\"));\n      document.querySelector(\"#restaurar\").addEventListener(\"click\", () => mover(\"restaurar\"));\n      document.querySelector(\"#archivo\").addEventListener(\"change\", () => {\n        const archivo = document.querySelector(\"#archivo\").files[0];\n        document.querySelector(\"#nota-archivo\").textContent = archivo ? archivo.name : \"\";\n        document.querySelector(\"#nota-audio\").hidden = true;\n      });\n      document.querySelector(\"#respuesta\").addEventListener(\"submit\", (evento) => {\n        const texto = document.querySelector(\"#texto\").value.trim();\n        const archivo = document.querySelector(\"#archivo\").files[0];\n        if (!texto && !archivo) evento.preventDefault();\n      });\n      document.querySelector(\"#grabar\").addEventListener(\"click\", async () => {\n        const boton = document.querySelector(\"#grabar\");\n        const nota = document.querySelector(\"#nota-audio\");\n        if (grabacion) {\n          grabacion.stop();\n          return;\n        }\n        const tipos = [\"audio/ogg;codecs=opus\", \"audio/mp4\"];\n        const tipo = tipos.find((candidato) => window.MediaRecorder && MediaRecorder.isTypeSupported(candidato));\n        if (!tipo) {\n          nota.hidden = false;\n          return;\n        }\n        let flujo;\n        try {\n          flujo = await navigator.mediaDevices.getUserMedia({ audio: true });\n        } catch {\n          nota.hidden = false;\n          nota.textContent = \"El navegador no permitió usar el micrófono.\";\n          return;\n        }\n        const recorder = new MediaRecorder(flujo, { mimeType: tipo });\n        const partes = [];\n        recorder.ondataavailable = (evento) => { if (evento.data.size) partes.push(evento.data); };\n        recorder.onstop = () => {\n          flujo.getTracks().forEach((pista) => pista.stop());\n          const extension = tipo.startsWith(\"audio/ogg\") ? \"ogg\" : \"m4a\";\n          const archivo = new File(partes, \"audio.\" + extension, { type: tipo.split(\";\")[0] });\n          const lista = new DataTransfer();\n          lista.items.add(archivo);\n          document.querySelector(\"#archivo\").files = lista.files;\n          document.querySelector(\"#nota-archivo\").textContent = \"Audio listo para enviar.\";\n          nota.hidden = true;\n          boton.textContent = \"Grabar audio\";\n          grabacion = null;\n        };\n        grabacion = recorder;\n        recorder.start();\n        boton.textContent = \"Detener\";\n      });\n      window.addEventListener(\"popstate\", () => { firma = \"\"; pedir(); });\n      pedir().then(conectar);\n      setInterval(() => { if (document.visibilityState === \"visible\") pedir(); }, 20000);\n    </script></body></html>";
